css:
.neon-circuit {
  width: 100%;
  height: 100%;
  background: radial-gradient(
    circle at center,
    rgba(0, 255, 255, 0.3),
    rgba(0, 0, 0, 0.9)
  );
  filter: url(#circuit-texture);
  position: relative;
  overflow: hidden;
}

.glow-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: repeating-linear-gradient(
    45deg,
    transparent,
    transparent 10px,
    rgba(0, 255, 255, 0.2) 10px,
    rgba(0, 255, 255, 0.2) 20px
  );
}
